const itemOrig = $('Processar 1 por Vez (Loop)').first().json;
const aiResponse = $input.first().json;

const rawCopy = aiResponse?.choices?.[0]?.message?.content || '';
// Limpa possíveis quebras indesejadas e formata
const cleanCopy = rawCopy.trim();

return [{
  json: {
    id: itemOrig.id,
    legenda_ia: cleanCopy
  }
}];

